from dataclasses import dataclass

@dataclass
class NonTypicalConfig:
    k: int
    n: int = 10
    digamma_position: int = 8
    digamma_mode: str = "sub"


def suite_A(k: int, n: int, digamma_pos: int, mode: str):
    termes = [k**p for p in range(1, n+1)]
    digamma = k**digamma_pos
    somme = sum(termes)
    if mode == "sub":
        digamma_calc = somme - digamma
    else:
        digamma_calc = somme + digamma
    return digamma_calc


def suite_B(k: int, n: int):
    termes = [k**p for p in range(1, n+2)]
    return sum(termes)


def reconstruire_premier_non_typique(cfg: NonTypicalConfig):
    A = suite_A(cfg.k, cfg.n, cfg.digamma_position, cfg.digamma_mode)
    B = suite_B(cfg.k, cfg.n)
    return (B - A) // (cfg.k**6)


def premiers_non_typiques(cfg: NonTypicalConfig, direction="croissant", count=10):
    base = reconstruire_premier_non_typique(cfg)
    if direction == "croissant":
        return [base + i for i in range(count)]
    else:
        return [max(2, base - i) for i in range(count)]

def repondre_rapport_non_typique(k: int, n: int = 10, direction: str = "croissant", count: int = 10):
    if k == 3:
        dig_pos, dig_mode = 8, "sub"
    elif k == 5:
        dig_pos, dig_mode = 7, "add"
    elif k == 6:
        dig_pos, dig_mode = 7, "sub"
    else:
        dig_pos, dig_mode = 8, "sub"

    cfg = NonTypicalConfig(k=k, n=n, digamma_position=dig_pos, digamma_mode=dig_mode)
    premier_n10 = reconstruire_premier_non_typique(cfg)
    liste = premiers_non_typiques(cfg, direction=direction, count=count)

    return {
        "rapport": f"1/{k}",
        "premier_n10": premier_n10,
        "premiers_generes": liste,
        "digamma_position": dig_pos,
        "digamma_mode": dig_mode
    }

def reconstruire_non_typique_interface(k: int):
    from src.spectral.non_typical_ratios import NonTypicalConfig, reconstruire_premier_non_typique
    cfg = NonTypicalConfig(k=k)
    return reconstruire_premier_non_typique(cfg)
